package com.aistock.notification.alert;
import com.aistock.common.*;import java.util.UUID;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Component;import org.springframework.http.HttpStatus;
@Component public class NotificationAccess {
 private static final org.slf4j.Logger LOG=org.slf4j.LoggerFactory.getLogger(NotificationAccess.class);
 private final NotificationIdentityClient client;private final String token;
 public NotificationAccess(NotificationIdentityClient client,@Value("${aistock.internal.token:}")String token){this.client=client;this.token=token;}
 public UUID resolve(String session){try{if(token.isBlank())throw unavailable();var r=client.resolve(new NotificationIdentityClient.ResolveInput(session),token);if(r==null||!"OK".equals(r.code())||r.data()==null||r.data().userId()==null){LOG.warn("Notification identity contract invalid: code={}, identityPresent={}",r==null?"NULL":r.code(),r!=null&&r.data()!=null);throw unavailable();}return r.data().userId();}catch(feign.FeignException e){LOG.warn("Notification account lookup rejected: status={}",e.status());if(e.status()==401)throw new BusinessException("AUTH_REQUIRED","登录已失效，请重新登录",HttpStatus.UNAUTHORIZED);throw unavailable();}catch(BusinessException e){throw e;}catch(RuntimeException e){LOG.warn("Notification account lookup failed: type={}",e.getClass().getSimpleName());throw unavailable();}}
 public boolean emailVerified(UUID owner,String session){try{var r=client.profile("AISTOCK_SESSION="+session);if(r==null||!"OK".equals(r.code())||r.data()==null||!owner.equals(r.data().userId())||!"ENABLED".equals(r.data().status()))throw unavailable();return r.data().emailVerified();}catch(feign.FeignException e){LOG.warn("Notification account lookup rejected: status={}",e.status());if(e.status()==401)throw new BusinessException("AUTH_REQUIRED","登录已失效，请重新登录",HttpStatus.UNAUTHORIZED);throw unavailable();}catch(BusinessException e){throw e;}catch(RuntimeException e){LOG.warn("Notification account lookup failed: type={}",e.getClass().getSimpleName());throw unavailable();}}
 private BusinessException unavailable(){return new BusinessException("ACCOUNT_SERVICE_UNAVAILABLE","账号服务暂不可用，请稍后重试",HttpStatus.SERVICE_UNAVAILABLE);}
}
